#!/usr/bin/env node

// Script to read .env.test and POST environment variables to the specified endpoint

const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (skip commented lines and empty lines)
const envVars = {};
for (const line of envContent.split('\n')) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) {
    continue;
  }
  const [key, ...valueParts] = trimmed.split('=');
  if (key && valueParts.length > 0) {
    const value = valueParts.join('=');
    envVars[key] = value;
  }
}

// JSON to POST
const payload = { environmentVariables: envVars };

console.log('📦 Environment variables to export:');
console.log(JSON.stringify(payload, null, 2));
console.log('');

// POST to the endpoint
const host = 'localhost';
const port = '3003';
const path = '/api/doc-export';
const method = 'POST';
const body = JSON.stringify(payload);

const options = {
  hostname: host,
  port: port,
  path: path,
  method: method,
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(body)
  }
};

console.log(`📤 Sending POST request to http://${host}:${port}${path}`);

const req = https.request(options, (res) => {
  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log(`\n✅ Response Status: ${res.statusCode} ${res.statusMessage}`);
    console.log('Response Body:');
    console.log(responseData);
  });
});

req.on('error', (error) => {
  console.error(`\n❌ Request failed: ${error.message}`);
  process.exit(1);
});

req.write(body);
req.end();

